select record_utc, concat('https://data.noise-planet.org/raw/', substring(user_uuid, 1, 2),'/', substring(user_uuid, 3, 2),'/', substring(user_uuid, 5, 2),'/',user_uuid,'/','track_',track_uuid,'.zip') download  from noisecapture_track nt, noisecapture_user nu, noisecapture_dump_track_envelope nd where nt.pk_track = nd.pk_track and nt.pk_user = nu.pk_user and
the_geom && st_expand('POINT({{longitude}} {{latitude}})'::geometry, {{radius_kilometers}} / 110.567, {{radius_kilometers}} / 110.567) and nt.time_length>{{min_mesurement_length}} and nt.time_length<{{max_mesurement_length}}  and nt.record_utc > {{min_time}} and nt.record_utc < {{max_time}}  ;
